mapper.select:
select shop_code, detailcode, doccode, lineno,
       goodscode, goodsname, spec, unit, warecode, warename, qualityflag, onhandflag, qty,
       saleprice, saleamount, costprice, costamount,
       batchcode, orderdetailcode, remark
  from sdsorder.u_f_docdetail_${tableSuffix}
 where shop_code = #{shopCode}
   and doccode = #{docCode}
 order by lineno

mapper.delete:
delete from sdsorder.u_f_docdetail_${tableSuffix}
 where shop_code = #{shopCode}
   and doccode = #{docCode}

mapper.select:
select coalesce(sum(t.qty), 0)
  from (

    ( select coalesce(sum(d.qty), 0) as qty
        from sdsorder.u_f_docdetail_${suffix} d
        join sdsorder.u_f_docmain_${suffix} m
          on m.shop_code = d.shop_code
         and m.doccode = d.doccode
       where m.shop_code = #{shopCode}
         and m.doctype = 'RK'
         and m.sourcedoccode = #{purchaseCode}
         and m.confirmstate = '待审核'
         and d.goodscode = #{goodsCode} )

  ) t

mapper.update:
update sdsorder.u_f_docdetail_${tableSuffix}
   set costprice = #{costPrice},
       costamount = #{costAmount}
 where shop_code = #{shopCode}
   and detailcode = #{detailCode}

update sdsorder.u_f_docdetail_${tableSuffix}
   set saleprice = #{salePrice},
       saleamount = #{saleAmount}
 where shop_code = #{shopCode}
   and detailcode = #{detailCode}
